## Debug: Capture Screenshot & Page Content

Create a diagnostic version that will save what the browser really sees.

```bash
cd ~/deepseek-cli
cat > deepseek-debug.js << 'EOF'
const puppeteer = require('puppeteer');
const fs = require('fs');

const COOKIES_FILE = './cookies.json';
const CHROMIUM_PATH = '/data/data/com.termux/files/usr/bin/chromium-browser';
const DEEPSEEK_BASE = 'https://chat.deepseek.com/';
const SESSION = process.argv[2] || '';

(async () => {
  const cookies = JSON.parse(fs.readFileSync(COOKIES_FILE, 'utf-8'));
  const cookieParams = cookies.map(c => ({
    name: c.name,
    value: c.value,
    domain: c.domain,
    path: c.path || '/',
    expires: c.expirationDate || -1,
    httpOnly: c.httpOnly || false,
    secure: c.secure || false,
    sameSite: c.sameSite || 'Lax',
  }));

  const browser = await puppeteer.launch({
    headless: 'new',
    executablePath: CHROMIUM_PATH,
    userDataDir: './browser-data',
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage', '--disable-gpu'],
  });

  const page = await browser.newPage();
  try {
    // Navigate
    const url = SESSION ? `${DEEPSEEK_BASE}a/chat/s/${SESSION}` : DEEPSEEK_BASE;
    await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 30000 });
    await page.setCookie(...cookieParams);
    await page.reload({ waitUntil: 'networkidle2', timeout: 30000 });

    // Wait a bit for JS to settle
    await page.waitForTimeout(3000);

    // Save screenshot
    await page.screenshot({ path: 'debug-screenshot.png', fullPage: false });
    console.log('Screenshot saved to debug-screenshot.png');

    // Save page text
    const bodyText = await page.evaluate(() => document.body.innerText);
    fs.writeFileSync('debug-page-text.txt', bodyText);
    console.log('Page text saved to debug-page-text.txt');

    // Save HTML (first 5000 chars)
    const html = await page.content();
    fs.writeFileSync('debug-page-html.txt', html.substring(0, 5000));
    console.log('HTML snippet saved to debug-page-html.txt');

    // Try to find any input element
    const inputInfo = await page.evaluate(() => {
      const inputs = Array.from(document.querySelectorAll('textarea, input[type="text"], [contenteditable="true"]'));
      return inputs.map(el => ({
        tag: el.tagName,
        placeholder: el.placeholder || el.getAttribute('placeholder') || '',
        contentEditable: el.contentEditable,
        ariaLabel: el.getAttribute('aria-label') || '',
      }));
    });
    console.log('Input elements found:', JSON.stringify(inputInfo, null, 2));

  } catch (err) {
    console.error('Debug error:', err);
  } finally {
    await browser.close();
  }
})();
EOF
```

Run it (with your session ID from earlier):
```bash
node deepseek-debug.js 13e4c76eb9c64f5ebbc92dd2c0a1d2b0
```

It will create three files:
- `debug-screenshot.png`
- `debug-page-text.txt`
- `debug-page-html.txt`

