  for (let i = 2; i < argv.length; i++) {
    if (argv[i] === '--new-chat') args.newChat = true;
    else if (argv[i] === '--session' && argv[i + 1]) {
      args.session = argv[i + 1];
      i++;
    } else filtered.push(argv[i]);
  }
  args.prompt = filtered.join(' ').trim();
  return args;
}

async function main() {
  const { prompt, newChat, session } = parseArgs(process.argv);
  if (!prompt) {
    console.error('Usage: node deepseek.js [--new-chat] [--session <ID>] "Your prompt"');
    process.exit(1);
  }

  if (!fs.existsSync(COOKIES_FILE)) {
    console.error(`Cookies file not found: ${COOKIES_FILE}`);
    process.exit(1);
  }

  const cookies = JSON.parse(fs.readFileSync(COOKIES_FILE, 'utf-8'));
  const cookieParams = cookies.map(c => ({
    name: c.name,
    value: c.value,
    domain: c.domain,
    path: c.path || '/',
    expires: c.expirationDate && c.expirationDate > 0 ? c.expirationDate : -1,
    httpOnly: c.httpOnly ?? false,
    secure: c.secure ?? true,
    sameSite: (c.sameSite || 'Lax').charAt(0).toUpperCase() + (c.sameSite || 'Lax').slice(1).toLowerCase(),
  }));

  const browser = await puppeteer.launch({
    headless: 'new',
    executablePath: CHROMIUM_PATH,
    userDataDir: './browser-data',
    args: [
      '--no-sandbox',
      '--disable-setuid-sandbox',
      '--disable-dev-shm-usage',
      '--disable-gpu',
      `--user-agent=${FIREFOX_UA}`,
    ],
  });

  const page = await browser.newPage();
  try {
    // 1. First load the base domain (will redirect to sign_in), but we set cookies on it
    await page.goto(DEEPSEEK_BASE, { waitUntil: 'domcontentloaded', timeout: 30000 });
    // Override User-Agent via CDP (more reliable)
    await page.setUserAgent(FIREFOX_UA);
    await page.setCookie(...cookieParams);
    await page.setUserAgent(FIREFOX_UA); // ensure cookies respect the UA

    // 2. Now navigate to the actual chat (session or base)
    const targetUrl = session ? `${DEEPSEEK_BASE}a/chat/s/${session}` : DEEPSEEK_BASE;
    await page.goto(targetUrl, { waitUntil: 'networkidle2', timeout: 30000 });
