## 1. Final Stealth Script – `deepseek.js`

```bash
cd ~/deepseek-cli
cat > deepseek.js << 'EOF'
const puppeteer = require('puppeteer');
const fs = require('fs');

const COOKIES_FILE = './cookies.json';
const CHROMIUM_PATH = '/data/data/com.termux/files/usr/bin/chromium-browser';
const FIREFOX_UA = 'Mozilla/5.0 (Android 14; Mobile; rv:150.0) Gecko/150.0 Firefox/150.0';
const DEEPSEEK_BASE = 'https://chat.deepseek.com/';
const INPUT_SEL = 'textarea[placeholder="Message DeepSeek"]';
const EXPERT_RADIO_SEL = 'div[data-model-type="expert"][role="radio"]';
const STOP_BUTTON_SEL = 'button[aria-label="Stop generating"]';
const MSG_SEL = 'div.ds-message[data-role="assistant"] .ds-markdown';
const DOWNLOADS_DIR = '/data/data/com.termux/files/home/storage/downloads';

const wait = (ms) => new Promise(r => setTimeout(r, ms));

function parseArgs(argv) {
  const args = { prompt: '', newChat: false, session: null };
  const filtered = [];
  for (let i = 2; i < argv.length; i++) {
    if (argv[i] === '--new-chat') args.newChat = true;
    else if (argv[i] === '--session' && argv[i + 1]) {
      args.session = argv[i + 1];
      i++;
    } else filtered.push(argv[i]);
  }
  args.prompt = filtered.join(' ').trim();
  return args;
}

async function main() {
  const { prompt, newChat, session } = parseArgs(process.argv);
  if (!prompt) {
    console.error('Usage: node deepseek.js [--new-chat] [--session <ID>] "Your prompt"');
    process.exit(1);
  }

  // Automatically find latest cookies*.json in Downloads
  const downloadFiles = fs.readdirSync(DOWNLOADS_DIR).filter(f => f.startsWith('cookies') && f.endsWith('.json'));
  if (downloadFiles.length === 0) {
    console.error('No cookies*.json in', DOWNLOADS_DIR);
    process.exit(1);
  }
  downloadFiles.sort((a, b) => fs.statSync(`${DOWNLOADS_DIR}/${b}`).mtimeMs - fs.statSync(`${DOWNLOADS_DIR}/${a}`).mtimeMs);
  const latestCookieFile = `${DOWNLOADS_DIR}/${downloadFiles[0]}`;
  console.log('📁 Using cookies:', downloadFiles[0]);

  const raw = JSON.parse(fs.readFileSync(latestCookieFile, 'utf-8'));
  const cookies = raw.cookies || raw;
  if (!Array.isArray(cookies)) {
    console.error('Cookies file must contain an array or .cookies field.');
    process.exit(1);
  }

  const cookieParams = cookies.map(c => {
    const cookie = {
      name: c.name,
      value: c.value,
      domain: c.domain,
      path: c.path || '/',
      httpOnly: c.httpOnly ?? false,
      secure: c.secure ?? true,
      sameSite: (c.sameSite || 'Lax').toLowerCase(),
      expires: c.expirationDate && c.expirationDate > 0 ? c.expirationDate : -1,
    };
    const valid = ['strict', 'lax', 'none'];
    if (!valid.includes(cookie.sameSite)) cookie.sameSite = 'lax';
    cookie.sameSite = cookie.sameSite.charAt(0).toUpperCase() + cookie.sameSite.slice(1);
    // Remove leading dot for hostOnly cookies
    if (c.hostOnly) cookie.domain = cookie.domain.replace(/^\./, '');
    return cookie;
  });

  const browser = await puppeteer.launch({
    headless: 'new',
    executablePath: CHROMIUM_PATH,
    userDataDir: './browser-data',
    args: [
      '--no-sandbox',
      '--disable-setuid-sandbox',
      '--disable-dev-shm-usage',
      '--disable-gpu',
      '--disable-blink-features=AutomationControlled',
      '--disable-features=IsolateOrigins,site-per-process',
      '--disable-web-security',
      '--disable-features=VizDisplayCompositor',
      `--user-agent=${FIREFOX_UA}`,
    ],
    ignoreDefaultArgs: ['--enable-automation'],
  });

  const page = await browser.newPage();
  await page.setUserAgent(FIREFOX_UA);
  await page.setExtraHTTPHeaders({
    'Accept-Language': 'en-US,en;q=0.9',
    'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8',
    'Sec-GPC': '1',
  });
  // Override navigator.webdriver
  await page.evaluateOnNewDocument(() => {
    Object.defineProperty(navigator, 'webdriver', { get: () => false });
  });

  try {
    await page.goto(DEEPSEEK_BASE, { waitUntil: 'domcontentloaded', timeout: 30000 });
    await page.setCookie(...cookieParams);
    await wait(1000);

    const targetUrl = session ? `${DEEPSEEK_BASE}a/chat/s/${session}` : DEEPSEEK_BASE;
    await page.goto(targetUrl, { waitUntil: 'networkidle2', timeout: 30000 });
    await wait(2000);

    if (page.url().includes('/sign_in')) {
      console.error('❌ Still on sign-in. Automation fingerprint likely detected.');
      console.error('💡 Run the manual login script: node deepseek-manual-login.js');
      process.exit(1);
    }

    await page.waitForSelector(INPUT_SEL, { timeout: 10000 });
    console.log('✅ Authenticated.');

    const expertRadio = await page.$(EXPERT_RADIO_SEL);
    if (expertRadio) {
      const isChecked = await page.evaluate(el => el.getAttribute('aria-checked'), expertRadio);
      if (isChecked !== 'true') {
        await expertRadio.click();
        await wait(800);
        console.log('🧠 Expert mode activated.');
      }
    }

    if (newChat && !session) {
      const newChatBtn = await page.$('button[aria-label="New chat"]');
      if (newChatBtn) {
        await newChatBtn.click();
        await wait(1500);
        console.log('🆕 New chat started.');
      }
    }

    const input = await page.$(INPUT_SEL);
    await input.click();
    await page.type(INPUT_SEL, prompt, { delay: 20 });
    await page.keyboard.press('Enter');

    await page.waitForSelector(STOP_BUTTON_SEL, { timeout: 15000 });
    await page.waitForFunction(
      (sel) => !document.querySelector(sel),
      { timeout: 300000 },
      STOP_BUTTON_SEL
    );

    const reply = await page.evaluate((sel) => {
      const msgs = document.querySelectorAll(sel);
      return msgs.length ? msgs[msgs.length - 1].innerText : '';
    }, MSG_SEL);

    console.log(reply || '⚠️ No reply captured.');
  } finally {
    await browser.close();
  }
}

main().catch(err => {
  console.error('💥 Fatal error:', err.message);
  process.exit(2);
});
EOF
```

