      const btn = await page.$('button[aria-label="New chat"]');
      if (btn) { await btn.click(); await wait(1500); }
    }

    // Send the prompt
    const input = await page.$(INPUT_SEL);
    await input.click();
    await page.type(INPUT_SEL, prompt, { delay: 20 });
    await page.keyboard.press('Enter');

    // -------------------------------------------------------------------
    // ROBUST COMPLETION DETECTION
    // -------------------------------------------------------------------
    // Method 1: Wait for the stop button to appear, then disappear
    let stopBtn = null;
    try {
      stopBtn = await page.waitForSelector('button[aria-label="Stop generating"]', { timeout: 8000 });
    } catch {
      // If not found, try alternative stop button label
      try {
        stopBtn = await page.waitForSelector('button[aria-label="Stop"]', { timeout: 5000 });
      } catch {
        console.log('⚠️ Stop button not found; falling back to text-watch method.');
      }
    }

    if (stopBtn) {
      // Wait until stop button disappears (generation finished)
      await page.waitForFunction(
        (sel) => !document.querySelector(sel),
        { timeout: 300000 },
        stopBtn._remoteObject ? 'button[aria-label="Stop generating"]' : 'button[aria-label="Stop"]'
      );
    } else {
      // Fallback: wait for the assistant message to appear and then stop growing
      // Grab the current message count
      const initialMsgCount = await page.$$eval(MSG_SEL, els => els.length);
      console.log(`Current assistant messages: ${initialMsgCount}. Waiting for new one...`);

      // Wait up to 120s for a new message to appear
      await page.waitForFunction(
        (sel, initial) => document.querySelectorAll(sel).length > initial,
        { timeout: 120000 },
        MSG_SEL, initialMsgCount
      );

      // Now wait for the message length to stabilise (no change for 4 seconds)
      let lastLength = 0;
      for (let i = 0; i < 60; i++) {   // max 120s of stability check
        await wait(2000);
        const currentLength = await page.evaluate((sel) => {
          const msgs = document.querySelectorAll(sel);
          return msgs.length ? msgs[msgs.length - 1].innerText.length : 0;
        }, MSG_SEL);
        if (currentLength === lastLength && currentLength > 0) {
          await wait(1000); // one extra second to be sure
          break;
        }
        lastLength = currentLength;
      }
    }

    // Extract the final assistant message
    const reply = await page.evaluate((sel) => {
      const msgs = document.querySelectorAll(sel);
      return msgs.length ? msgs[msgs.length - 1].innerText : '';
    }, MSG_SEL);

    console.log(reply || '⚠️ No reply captured.');
  } finally {
    await browser.close();
  }
})();
