const ASSISTANT_MSG_SEL = 'div.ds-message[data-role="assistant"] .ds-markdown';
const USER_MSG_SEL = 'div.ds-message[data-role="user"]';

const wait = ms => new Promise(r => setTimeout(r, ms));

function parseArgs(argv) {
  const args = { prompt: '', newChat: false, session: null, edit: false };
  const filtered = [];
  for (let i = 2; i < argv.length; i++) {
    if (argv[i] === '--new-chat') args.newChat = true;
    else if (argv[i] === '--edit') args.edit = true;
    else if (argv[i] === '--session' && argv[i + 1]) {
      args.session = argv[i + 1];
      i++;
    } else filtered.push(argv[i]);
  }
  args.prompt = filtered.join(' ').trim();
  return args;
}

// Find the send button – it's usually a button that contains an SVG with data-icon="send"
async function findSendButton(page) {
  const sendBtn = await page.evaluateHandle(() => {
    const buttons = Array.from(document.querySelectorAll('button, [role="button"]'));
    const svgSend = buttons.find(btn => {
      const svg = btn.querySelector('svg[data-icon="send"]');
      const aria = btn.getAttribute('aria-label')?.toLowerCase();
      return svg || (aria && (aria.includes('send') || aria.includes('submit')));
    });
    return svgSend || null;
  });
  return sendBtn.asElement() ? sendBtn : null;
}

// Click the edit button on the last user message
async function editLastUserMessage(page) {
  const userMsgs = await page.$$(USER_MSG_SEL);
  if (userMsgs.length === 0) return false;
  const lastMsg = userMsgs[userMsgs.length - 1];
  const editBtn = await lastMsg.$('button[aria-label="Edit"], div[role="button"][aria-label="Edit"]');
  if (!editBtn) {
    console.log('⚠️ Edit button not found on last user message.');
    return false;
  }
  await editBtn.click();
  await wait(800);
  // Now the textarea inside that message should be editable
  const editArea = await lastMsg.$('textarea');
  if (editArea) {
    // Clear existing text
    await editArea.click({ clickCount: 3 });
    await editArea.press('Backspace');
    return true;
  }
  return false;
}

async function main() {
  const { prompt, newChat, session, edit } = parseArgs(process.argv);
  if (!prompt) {
    console.error('Usage: node deepseek.js [--new-chat] [--session <ID>] [--edit] "Your prompt"');
    process.exit(1);
  }

  const browser = await puppeteer.launch({
    headless: 'new',
    executablePath: CHROMIUM_PATH,
    userDataDir: './browser-data',
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage', '--disable-gpu'],
  });

  const page = await browser.newPage();
  try {
    const targetUrl = session ? `${DEEPSEEK_BASE}a/chat/s/${session}` : DEEPSEEK_BASE;
    await page.goto(targetUrl, { waitUntil: 'networkidle2', timeout: 30000 });
    await wait(2000);

    if (page.url().includes('/sign_in')) {
      console.error('❌ Not authenticated. Run manual login again.');
      process.exit(1);
    }

    await page.waitForSelector(INPUT_SEL, { timeout: 10000 });
    console.log('✅ Authenticated.');

    // Expert mode
    const expertRadio = await page.$(EXPERT_RADIO_SEL);
    if (expertRadio) {
      const checked = await page.evaluate(el => el.getAttribute('aria-checked'), expertRadio);
      if (checked !== 'true') {
        await expertRadio.click();
        await wait(800);
      }
    }

    // New chat if requested (only when no session and --new-chat)
    if (newChat && !session) {
      const newChatBtn = await page.$('button[aria-label="New chat"]');
      if (newChatBtn) {
        await newChatBtn.click();
        await wait(1500);
        console.log('🆕 New chat started.');
      }
    }

    // Handle --edit: edit last user message before sending new prompt
    if (edit) {
      const edited = await editLastUserMessage(page);
      if (edited) {
        await page.type('textarea', prompt, { delay: 20 });
      } else {
        console.log('⚠️ Edit failed; falling back to main input.');
        await page.click(INPUT_SEL);
        await page.type(INPUT_SEL, prompt, { delay: 20 });
      }
    } else {
      // Normal send via main input
      const input = await page.$(INPUT_SEL);
      await input.click();
      await page.type(INPUT_SEL, prompt, { delay: 20 });
    }

    // Wait for send button to appear (dynamic) and click it
    await wait(500);
    const sendBtn = await findSendButton(page);
    if (sendBtn) {
      await sendBtn.click();
      console.log('📤 Message sent.');
    } else {
      // Fallback: try Shift+Enter or Ctrl+Enter
      console.log('⚠️ No send button found; trying Shift+Enter...');
      await page.keyboard.down('Shift');
      await page.keyboard.press('Enter');
      await page.keyboard.up('Shift');
    }

    // Completion detection
    // Wait for stop button to appear and then disappear
    let stopBtn = null;
    try {
      stopBtn = await page.waitForSelector(
        'button[aria-label="Stop generating"], button[aria-label="Stop"]',
        { timeout: 8000 }
      );
    } catch {}
    if (stopBtn) {
      await page.waitForFunction(
        () => !document.querySelector('button[aria-label="Stop generating"]') &&
               !document.querySelector('button[aria-label="Stop"]'),
        { timeout: 300000 }
      );
    } else {
      // Fallback: wait for new assistant message content to stabilise
      console.log('⏳ Watching for assistant reply...');
      const initialCount = await page.$$eval(ASSISTANT_MSG_SEL, els => els.length);
      await page.waitForFunction(
        (sel, init) => document.querySelectorAll(sel).length > init,
        { timeout: 120000 },
        ASSISTANT_MSG_SEL, initialCount
      );
      // Wait until text stops growing (poll every 2s for 120s)
      let lastLength = 0;
      for (let i = 0; i < 60; i++) {
        await wait(2000);
        const msgs = await page.$$eval(ASSISTANT_MSG_SEL, els => els.length);
        if (msgs > 0) {
          const textLen = await page.$eval(
            `${ASSISTANT_MSG_SEL}:last-child`,
            el => el.innerText.length
          );
          if (textLen === lastLength && textLen > 0) {
            await wait(1000);
            break;
          }
          lastLength = textLen;
        }
      }
    }

    // Extract final assistant reply
    const reply = await page.evaluate((sel) => {
      const msgs = document.querySelectorAll(sel);
      return msgs.length ? msgs[msgs.length - 1].innerText : '';
    }, ASSISTANT_MSG_SEL);

    console.log(reply || '⚠️ No reply captured.');
  } finally {
    await browser.close();
  }
}

main().catch(err => {
  console.error('💥 Fatal error:', err.message);
  process.exit(2);
});
