      const initialCount = await page.$$eval(ASSISTANT_MSG_SEL, els => els.length);
      await page.waitForFunction(
        (sel, init) => document.querySelectorAll(sel).length > init,
        { timeout: 120000 },
        ASSISTANT_MSG_SEL, initialCount
      );
      let lastLength = 0;
      for (let i = 0; i < 60; i++) {
        await wait(2000);
