    console.log('📤 Message sent.');

    // -------------------------------------------------
    // WAIT FOR REPLY
    // We'll race two conditions:
    // 1. Stop button appears and then disappears
    // 2. Assistant message count increases and text stabilises
    // -------------------------------------------------
    const startTime = Date.now();
    const maxWait = 300_000; // 5 minutes

    // Helper to get last assistant message text
    const getLastAssistantText = async () => {
      const msgs = await page.$$eval(ASSISTANT_MSG_SEL, els => {
        return els.length ? els[els.length - 1].innerText : '';
      });
      return msgs;
    };

    let reply = '';
    let stopBtnDetected = false;
    let stopBtnDisappeared = false;

    // Polling loop (every 500 ms)
    while (Date.now() - startTime < maxWait) {
      // Check stop button
      const stopBtn = await page.$('button[aria-label="Stop generating"], button[aria-label="Stop"]');
      if (stopBtn) {
        stopBtnDetected = true;
      } else if (stopBtnDetected) {
        // It was there, now it's gone -> generation finished
        stopBtnDisappeared = true;
        break;
      }

      // Check assistant messages
      const currentMsgs = await page.$$eval(ASSISTANT_MSG_SEL, els => els.length);
      if (currentMsgs > 0) {
        const text = await getLastAssistantText();
        if (text.trim().length > 0) {
          // Wait a bit and see if it's still growing
          await wait(1500);
          const textAfter = await getLastAssistantText();
          if (textAfter === text) {
            // Stable for 1.5 seconds, consider it done
            reply = textAfter;
            break;
          }
        }
      }

      await wait(500);
    }

    // If we broke out of the loop because of stop button disappearance but no reply yet,
    // grab the last assistant message now
    if (stopBtnDisappeared && !reply) {
      reply = await getLastAssistantText();
    }

    console.log(reply || '⚠️ No reply captured.');

    // Print the current session ID for easy continuation
    const currentUrl = new URL(page.url());
    const sessionId = currentUrl.pathname.split('/').pop();
    if (sessionId && sessionId.length > 10) {
      console.log(`🔗 Session ID: ${sessionId} (use --session ${sessionId})`);
    }

  } finally {
    await browser.close();
  }
}

main().catch(err => {
  console.error('💥 Fatal error:', err.message);
  process.exit(2);
});
EOF
