const INDEX_FILE = './chat-index.json';

const wait = ms => new Promise(r => setTimeout(r, ms));

function parseArgs(argv) {
  const args = { prompt: '', newChat: false, session: null, edit: false, title: null };
  const filtered = [];
  for (let i = 2; i < argv.length; i++) {
    if (argv[i] === '--new-chat') args.newChat = true;
    else if (argv[i] === '--edit') args.edit = true;
    else if (argv[i] === '--session' && argv[i + 1]) {
      args.session = argv[i + 1]; i++;
    } else if (argv[i] === '--title' && argv[i + 1]) {
      args.title = argv[i + 1]; i++;
