## 2. Create the final `deepseek.js`

```bash
cd ~/deepseek-cli
cat > deepseek.js << 'CEOF'
const puppeteer = require('puppeteer');
const readline = require('readline');
const CHROMIUM_PATH = '/data/data/com.termux/files/usr/bin/chromium-browser';
const DEEPSEEK_BASE = 'https://chat.deepseek.com/';
const INPUT_SEL = 'textarea[placeholder="Message DeepSeek"]';
const EXPERT_RADIO_SEL = 'div[data-model-type="expert"][role="radio"]';
const ASSISTANT_MSG_SEL = 'div.ds-message[data-role="assistant"] .ds-markdown';
const USER_MSG_SEL = 'div.ds-message[data-role="user"]';
const SEND_BTN_SEL = '._52c986b';
const EDIT_PENCIL_SEL = '.d4910adc';

const wait = ms => new Promise(r => setTimeout(r, ms));

// Global browser and page for the session
let browser, page;

// ---------- Helpers ----------
async function typeIntoReactInput(el, text) {
  await el.evaluate((node, value) => {
    const nativeSetter = Object.getOwnPropertyDescriptor(
      window.HTMLTextAreaElement.prototype, 'value'
    ).set;
    nativeSetter.call(node, value);
    node.dispatchEvent(new Event('input', { bubbles: true }));
  }, text);
}

// Inject a MutationObserver that saves the latest assistant reply to window.__deepseekReply
async function setupReplyCapture() {
  await page.evaluate(() => {
    window.__deepseekReply = null;
    window.__deepseekDone = false;
    const targetNode = document.body;
    const config = { childList: true, subtree: true, characterData: true };

    const observer = new MutationObserver((mutations) => {
      // Look for the last assistant message
      const msgs = document.querySelectorAll('div.ds-message[data-role="assistant"] .ds-markdown');
      if (msgs.length > 0) {
        const last = msgs[msgs.length - 1];
        window.__deepseekReply = last.innerText;
      }
      // Check if the stop button disappeared (or never appeared) and the reply is non-empty
      const stopBtn = document.querySelector('button[aria-label="Stop generating"], button[aria-label="Stop"]');
      if (!stopBtn && window.__deepseekReply && window.__deepseekReply.trim().length > 0) {
        window.__deepseekDone = true;
        observer.disconnect();
      }
    });
    observer.observe(targetNode, config);

    // Also set a fallback timeout: if after 5 seconds of no mutations, set done
    let timeout;
    const resetTimeout = () => {
      clearTimeout(timeout);
      timeout = setTimeout(() => {
        if (window.__deepseekReply && window.__deepseekReply.trim().length > 0) {
          window.__deepseekDone = true;
          observer.disconnect();
        }
      }, 5000);
    };
    observer.originalReset = resetTimeout;
    // Override the observer to also call resetTimeout on mutations
    const originalCallback = observer._callback;
    observer._callback = (mutations) => {
      originalCallback(mutations);
      resetTimeout();
    };
    resetTimeout();
  });
}

// Wait for the observer to set __deepseekDone
async function waitForReply(timeoutMs = 300000) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    const done = await page.evaluate(() => window.__deepseekDone);
    if (done) break;
    await wait(500);
  }
  const reply = await page.evaluate(() => window.__deepseekReply);
  return reply || '';
}

// ---------- Main session setup ----------
async function initSession(sessionId = null) {
  browser = await puppeteer.launch({
    headless: 'new',
    executablePath: CHROMIUM_PATH,
    userDataDir: './browser-data',
    args: ['--no-sandbox','--disable-setuid-sandbox','--disable-dev-shm-usage','--disable-gpu'],
  });

  page = await browser.newPage();
  const targetUrl = sessionId ? `${DEEPSEEK_BASE}a/chat/s/${sessionId}` : DEEPSEEK_BASE;
  await page.goto(targetUrl, { waitUntil: 'networkidle2', timeout: 30000 });
  await wait(2000);

  if (page.url().includes('/sign_in')) {
    console.error('❌ Not authenticated. Run manual login again.');
    await browser.close();
    process.exit(1);
  }

  await page.waitForSelector(INPUT_SEL, { timeout: 10000 });
  console.log('✅ Authenticated.');

  // Expert mode
  const expertRadio = await page.$(EXPERT_RADIO_SEL);
  if (expertRadio) {
    const checked = await page.evaluate(el => el.getAttribute('aria-checked'), expertRadio);
    if (checked !== 'true') {
      await expertRadio.click();
      await wait(800);
    }
  }

  // Set up response capture
  await setupReplyCapture();
}

// ---------- Send a message (supports --edit) ----------
async function sendMessage(prompt, edit = false) {
  let targetTextarea = null;

  if (edit) {
    const userMsgs = await page.$$(USER_MSG_SEL);
    if (userMsgs.length > 0) {
      const lastMsg = userMsgs[userMsgs.length - 1];
      const pencil = await lastMsg.$(EDIT_PENCIL_SEL);
      if (pencil) {
        await pencil.click();
        await wait(600);
        const editArea = await lastMsg.$('textarea');
        if (editArea) {
          targetTextarea = editArea;
        }
      }
    }
  }

  if (!targetTextarea) {
    targetTextarea = await page.$(INPUT_SEL);
  }

  await targetTextarea.click();
  await typeIntoReactInput(targetTextarea, prompt);

  // Wait for send button to enable
  await page.waitForFunction(
    (sel) => {
      const btn = document.querySelector(sel);
      return btn && btn.getAttribute('aria-disabled') !== 'true';
    },
    { timeout: 10000 },
    SEND_BTN_SEL
  );
  const sendBtn = await page.$(SEND_BTN_SEL);
  await sendBtn.click();

  // Re-arm the observer for the new reply
  await setupReplyCapture();
  const reply = await waitForReply();
  return reply;
}

// ---------- List recent sessions ----------
async function listSessions() {
  // Click the sidebar toggle if needed (might need to expand)
  const sidebarBtn = await page.$('button[aria-label="Toggle sidebar"]');
  if (sidebarBtn) {
    await sidebarBtn.click();
    await wait(1000);
  }

  const sessions = await page.evaluate(() => {
    const items = document.querySelectorAll('._546d736');
    return Array.from(items).map((item, idx) => {
      const titleEl = item.querySelector('.c08e6e93');
      const title = titleEl ? titleEl.innerText.trim() : '(no title)';
      // Extract session ID from the item's onclick or data attribute; easiest: click would navigate.
      // We can just store the index; later click the item to navigate.
      return { index: idx, title };
    });
  });
  return sessions;
}

// ---------- CLI parsing ----------
async function main() {
  const args = process.argv.slice(2);
  let sessionId = null;
  let editMode = false;
  let loopMode = false;
  let listMode = false;
  let promptIndex = args.findIndex(a => !a.startsWith('--'));
  let prompt = '';
  if (promptIndex > -1) {
    prompt = args.slice(promptIndex).join(' ');
    args.splice(promptIndex);
  }

  for (const arg of args) {
    if (arg === '--session' && args.indexOf(arg) + 1 < args.length) {
      sessionId = args[args.indexOf(arg) + 1];
    } else if (arg === '--edit') {
      editMode = true;
    } else if (arg === '--loop') {
      loopMode = true;
    } else if (arg === '--list') {
      listMode = true;
    }
  }

  if (listMode) {
    // Temporary browser to list sessions
    await initSession();
    const sessions = await listSessions();
    console.log('📋 Recent chat sessions:');
    sessions.forEach(s => console.log(`  [${s.index}] ${s.title}`));
    await browser.close();
    return;
  }

  if (loopMode) {
    await initSession(sessionId);
    console.log('🔄 Loop mode – type prompts and press Enter. Ctrl+C to quit.');
    const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
    for await (const line of rl) {
      if (line.trim()) {
        const reply = await sendMessage(line.trim(), editMode);
        console.log(reply);
        // After first message, editMode is effectively off, unless user wants to keep editing the same user message?
        editMode = false;
      }
    }
    await browser.close();
    return;
  }

  // Single prompt mode
  if (!prompt) {
    console.error('Usage: deepseek.js [--session <ID>] [--edit] [--loop] [--list] "Your prompt"');
    process.exit(1);
  }

  await initSession(sessionId);
  const reply = await sendMessage(prompt, editMode);
  console.log(reply);
  // Print session ID
  const currentUrl = new URL(page.url());
  const id = currentUrl.pathname.split('/').pop();
  if (id && id.length > 10) console.log(`🔗 Session ID: ${id}`);
  await browser.close();
}

main().catch(err => {
  console.error('💥 Fatal error:', err.message);
  process.exit(2);
});
CEOF
