const puppeteer = require('puppeteer');
const readline = require('readline');
const CHROMIUM_PATH = '/data/data/com.termux/files/usr/bin/chromium-browser';
const DEEPSEEK_BASE = 'https://chat.deepseek.com/';
const INPUT_SEL = 'textarea[placeholder="Message DeepSeek"]';
const EXPERT_RADIO_SEL = 'div[data-model-type="expert"][role="radio"]';
const SEND_BTN_SEL = '._52c986b';
const EDIT_PENCIL_SEL = '.d4910adc';
const USER_MSG_SEL = 'div.ds-message[data-role="user"]';
// Fallback selectors for assistant message
const ASSISTANT_SELECTORS = [
    'div.ds-message[data-role="assistant"] .ds-markdown',
    'div.ds-message[data-role="assistant"]',
    '.ds-markdown'
];

const wait = ms => new Promise(r => setTimeout(r, ms));

let browser, page;

// ---------- React Input Helper ----------
async function typeIntoReactInput(el, text) {
    await el.evaluate((node, value) => {
        const nativeSetter = Object.getOwnPropertyDescriptor(
            window.HTMLTextAreaElement.prototype, 'value'
        ).set;
        nativeSetter.call(node, value);
        node.dispatchEvent(new Event('input', { bubbles: true }));
        node.dispatchEvent(new Event('change', { bubbles: true }));
    }, text);
}

// ---------- Find working assistant selector ----------
async function findAssistantSelector() {
    for (const sel of ASSISTANT_SELECTORS) {
        const exists = await page.$(sel);
        if (exists) return sel;
    }
    return null;
}

// ---------- Wait for reply (polling stabilizer) ----------
async function waitForReply(timeoutMs = 300000) {
    const start = Date.now();
    const assistantSel = await findAssistantSelector();
    if (!assistantSel) return '';

    // Wait for first assistant message to appear
    try {
        await page.waitForSelector(assistantSel, { timeout: 30000 });
    } catch {
        return '';
    }

    // Poll until text stabilizes (no change for 4 seconds)
    let lastText = '';
    let stableCount = 0;
    while (Date.now() - start < timeoutMs) {
        await wait(1000);
        const currentText = await page.evaluate((sel) => {
            const el = document.querySelector(sel);
            return el ? el.innerText.trim() : '';
        }, assistantSel);
        if (currentText === lastText && currentText.length > 0) {
            stableCount++;
            if (stableCount >= 4) {
                return currentText;
            }
        } else {
            stableCount = 0;
            lastText = currentText;
        }
    }
    return lastText;
}

// ---------- Send a message ----------
async function sendMessage(prompt, edit = false) {
    let targetTextarea = null;

    if (edit) {
        const userMsgs = await page.$$(USER_MSG_SEL);
        if (userMsgs.length > 0) {
            const lastMsg = userMsgs[userMsgs.length - 1];
            const pencil = await lastMsg.$(EDIT_PENCIL_SEL);
            if (pencil) {
                await pencil.click();
                await wait(600);
                const editArea = await lastMsg.$('textarea');
                if (editArea) {
                    targetTextarea = editArea;
                    console.log('✏️ Edit mode activated.');
                }
            }
        }
    }

    if (!targetTextarea) {
        targetTextarea = await page.$(INPUT_SEL);
    }

    await targetTextarea.click();
    await wait(200);
    await typeIntoReactInput(targetTextarea, prompt);

    // Wait for send button to enable and click
    await page.waitForFunction(
        (sel) => {
            const btn = document.querySelector(sel);
            return btn && btn.getAttribute('aria-disabled') !== 'true';
        },
        { timeout: 10000 },
        SEND_BTN_SEL
    );
    const sendBtn = await page.$(SEND_BTN_SEL);
    await sendBtn.click();
    console.log('📤 Message sent.');

    const reply = await waitForReply();
    return reply;
}

// ---------- List sessions ----------
async function listSessions() {
    await page.waitForTimeout(2000);
    const sessions = await page.evaluate(() => {
        const items = document.querySelectorAll('._546d736, .ds-conversation-item, [class*="conversation"]');
        return Array.from(items).map((item, idx) => {
            const titleEl = item.querySelector('.c08e6e93, .ds-conversation-title, [class*="title"]');
            const title = titleEl ? titleEl.innerText.trim() : '(no title)';
            return { index: idx, title };
        });
    });
    return sessions;
}

// ---------- Init session ----------
async function initSession(sessionId = null) {
    browser = await puppeteer.launch({
        headless: 'new',
        executablePath: CHROMIUM_PATH,
        userDataDir: './browser-data',
        args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage', '--disable-gpu'],
    });

    page = await browser.newPage();
    const targetUrl = sessionId ? `${DEEPSEEK_BASE}a/chat/s/${sessionId}` : DEEPSEEK_BASE;
    await page.goto(targetUrl, { waitUntil: 'networkidle2', timeout: 30000 });
    await wait(2000);

    if (page.url().includes('/sign_in')) {
        console.error('❌ Not authenticated. Run manual login again.');
        await browser.close();
        process.exit(1);
    }

    await page.waitForSelector(INPUT_SEL, { timeout: 10000 });
    console.log('✅ Authenticated.');

    // Expert mode
    const expertRadio = await page.$(EXPERT_RADIO_SEL);
    if (expertRadio) {
        const checked = await page.evaluate(el => el.getAttribute('aria-checked'), expertRadio);
        if (checked !== 'true') {
            await expertRadio.click();
            await wait(800);
        }
    }
}

// ---------- CLI ----------
async function main() {
    const args = process.argv.slice(2);
    let sessionId = null;
    let editMode = false;
    let loopMode = false;
    let listMode = false;
    let prompt = '';
    let promptIndex = args.findIndex(a => !a.startsWith('--'));
    if (promptIndex > -1) {
        prompt = args.slice(promptIndex).join(' ');
        args.splice(promptIndex);
    }

    for (let i = 0; i < args.length; i++) {
        if (args[i] === '--session' && args[i + 1]) {
            sessionId = args[i + 1];
            i++;
        } else if (args[i] === '--edit') {
            editMode = true;
        } else if (args[i] === '--loop') {
            loopMode = true;
        } else if (args[i] === '--list') {
            listMode = true;
        }
    }

    if (listMode) {
        await initSession();
        const sessions = await listSessions();
        console.log('📋 Recent chat sessions:');
        sessions.forEach(s => console.log(`  [${s.index}] ${s.title}`));
        await browser.close();
        return;
    }

    if (loopMode) {
        await initSession(sessionId);
        console.log('🔄 Loop mode – type prompts and press Enter. Ctrl+C to quit.');
        const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
        for await (const line of rl) {
            if (line.trim()) {
                const reply = await sendMessage(line.trim(), editMode);
                console.log(reply);
                editMode = false;
            }
        }
        await browser.close();
        return;
    }

    // Single prompt
    if (!prompt) {
        console.error('Usage: deepseek.js [--session <ID>] [--edit] [--loop] [--list] "Your prompt"');
        process.exit(1);
    }

    await initSession(sessionId);
    const reply = await sendMessage(prompt, editMode);
    console.log(reply);
    const currentUrl = new URL(page.url());
    const id = currentUrl.pathname.split('/').pop();
    if (id && id.length > 10) console.log(`🔗 Session ID: ${id}`);
    await browser.close();
}

main().catch(err => {
    console.error('💥 Fatal error:', err.message);
    process.exit(2);
});
