    try {
        await page.waitForSelector(ASSISTANT_MSG_SEL, { timeout: 30000 });
    } catch {
        return ''; // never appeared
    }

    // Poll until text stabilizes (no change for 3 seconds)
    let lastText = '';
    let stableCount = 0;
