    if (checked !== 'true') { await expert.click(); await wait(800); }
  }
  console.log('✅ Authenticated.');
}

// ---------- Edit a specific user message ----------
// index: -1 = last, 0 = first, etc.
async function editMessageByIndex(index, newText) {
  const userMsgs = await page.$$(USER_MSG_SEL);
  if (userMsgs.length === 0) {
    console.error('❌ No user messages found.');
    return false;
  }
  const idx = index < 0 ? userMsgs.length + index : index;
  if (idx < 0 || idx >= userMsgs.length) {
    console.error(`❌ Invalid message index: ${index} (total: ${userMsgs.length})`);
