## 🧪 One‑Shot Discovery Script

Create this **once**, run it, and it will output `upload-config.json` with everything your CLI needs.

```bash
cd ~/deepseek-cli
cat > discover-upload.js << 'CEOF'
const puppeteer = require('puppeteer');
const fs = require('fs');
const CHROMIUM_PATH = '/data/data/com.termux/files/usr/bin/chromium-browser';
const INPUT_SEL = 'textarea[placeholder="Message DeepSeek"]';
const INSTANT_RADIO_SEL = 'div[data-model-type="default"][role="radio"]';

(async () => {
  const browser = await puppeteer.launch({
    headless: 'new',
    executablePath: CHROMIUM_PATH,
    userDataDir: './browser-data',
    args: ['--no-sandbox','--disable-setuid-sandbox','--disable-dev-shm-usage','--disable-gpu'],
  });

  const page = await browser.newPage();
  let uploadRequest = null;

  // Intercept network to capture the upload POST
  await page.setRequestInterception(true);
  page.on('request', req => {
    if (req.url().includes('/api/') && req.method() === 'POST') {
      // Possible upload endpoint – log details
      if (req.hasPostData() && req.postData().includes('Content-Disposition')) {
        uploadRequest = {
          url: req.url(),
          method: req.method(),
          headers: req.headers(),
          postData: req.postData().substring(0, 2000) // keep first 2k for analysis
        };
      }
    }
    req.continue();
  });

  // Listen for the actual response
  let uploadResponse = null;
  page.on('response', async resp => {
    if (uploadRequest && resp.request().url() === uploadRequest.url) {
      try {
        uploadResponse = {
          status: resp.status(),
          headers: resp.headers(),
          body: await resp.text()
        };
      } catch {}
    }
  });

  try {
    // Navigate to a fresh chat (toggle still visible)
    await page.goto('https://chat.deepseek.com/', { waitUntil: 'networkidle2' });
    if (page.url().includes('/sign_in')) {
      console.log('❌ Not authenticated – run manual login first.');
      await browser.close();
      process.exit(1);
    }
    await page.waitForSelector(INPUT_SEL);

    // Switch to Instant mode
    const instantRadio = await page.$(INSTANT_RADIO_SEL);
    if (instantRadio) {
      const checked = await page.evaluate(el => el.getAttribute('aria-checked'), instantRadio);
      if (checked !== 'true') await instantRadio.click();
      await new Promise(r => setTimeout(r, 800));
    }

    // Create a tiny test file
    fs.writeFileSync('/tmp/deepseek-test.txt', 'hello', 'utf8');

    // Click the paperclip button (aria-label may be "Upload file" or similar)
    const uploadBtn = await page.$('button[aria-label="Upload file"], button[aria-label="Attach file"]');
    if (!uploadBtn) {
      console.log('⚠️ Upload button not found – is the paperclip visible?');
      await browser.close();
      return;
    }
    await uploadBtn.click();
    await new Promise(r => setTimeout(r, 500));

    // Find the file input (hidden)
    const fileInput = await page.$('input[type="file"]');
    if (!fileInput) {
      console.log('⚠️ File input not found after clicking paperclip.');
      await browser.close();
      return;
    }

    // Upload the test file
    await fileInput.uploadFile('/tmp/deepseek-test.txt');
    await new Promise(r => setTimeout(r, 3000)); // wait for upload to complete

    // Save the captured request/response
    const config = { uploadRequest, uploadResponse };
    fs.writeFileSync('upload-config.json', JSON.stringify(config, null, 2));
    console.log('✅ Upload configuration saved to upload-config.json');
    console.log('URL:', uploadRequest?.url);
    console.log('Response status:', uploadResponse?.status);

  } catch (e) {
    console.error(e);
  } finally {
    await browser.close();
  }
})();
CEOF
```

