// Inside deepseek.js
const config = JSON.parse(fs.readFileSync('upload-config.json'));
const fileBuffer = fs.readFileSync(filePath);
const base64 = fileBuffer.toString('base64');

const uploadResult = await page.evaluate(async (url, headers, fileData, fileName) => {
  const formData = new FormData();
  const blob = new Blob([Uint8Array.from(atob(fileData), c => c.charCodeAt(0))]);
  formData.append('file', blob, fileName);

  const res = await fetch(url, { method: 'POST', headers, body: formData });
  return res.json();
}, config.uploadRequest.url, config.uploadRequest.headers, base64, path.basename(filePath));

// Then append the returned file reference to the prompt before sending
```

