// ---------- CLI ----------
async function main() {
  const args = process.argv.slice(2);
  let sessionId = null, editMode = false, loopMode = false, listMode = false, showLog = false;
  let systemPromptFile = null, attachFile = null;
  let prompt = '';
  let promptIndex = args.findIndex(a => !a.startsWith('--'));
