    else if (args[i] === '--system-prompt-file' && args[i+1]) { try { systemPrompt = fs.readFileSync(args[i+1], 'utf8').trim(); } catch {} i++; }
    else if (args[i] === '--attach' && args[i+1]) { attachFile = args[i+1]; i++; }
  }

